               {"x0": 9, "x1": 52, "l": "Contention Access Period (CAP)", "c": "#fdba74", "at": 2, "hl": 4, "hlEnd": 6, "fs": 26},
               {"x0": 52, "x1": 72, "l": "GTS 3", "c": "#4ade80", "at": 6, "hl": 6, "hlEnd": 8},
               {"x0": 72, "x1": 84, "l": "GTS 2", "c": "#4ade80", "at": 6, "hl": 6, "hlEnd": 8},
               {"x0": 84, "x1": 97, "l": "GTS 1", "c": "#4ade80", "at": 6, "hl": 6, "hlEnd": 8},
